∀ {m n : T07_012.BMonoid} {toFun : m.carrier → n.carrier} {map_one : toFun m.one = n.one}
  {toFun_1 : m.carrier → n.carrier} {map_one_1 : toFun_1 m.one = n.one},
  { toFun := toFun, map_one := map_one } = { toFun := toFun_1, map_one := map_one_1 } → toFun = toFun_1

∀ {carrier : Type} {mul : carrier → carrier → carrier} {one : carrier} {one_mul : ∀ (a : carrier), mul one a = a}
  {carrier_1 : Type} {mul_1 : carrier_1 → carrier_1 → carrier_1} {one_1 : carrier_1}
  {one_mul_1 : ∀ (a : carrier_1), mul_1 one_1 a = a},
  { carrier := carrier, mul := mul, one := one, one_mul := one_mul } =
      { carrier := carrier_1, mul := mul_1, one := one_1, one_mul := one_mul_1 } →
    carrier = carrier_1 ∧ HEq mul mul_1 ∧ HEq one one_1
